function omni(){if(!DATA.markets)return heading('Omni Markets')+pageRangeToolbar()+dataUnavailable('Omni','markets');const market=selectedMarket();if(market)return marketDetail(market);const contract=route.params.get('contract')||'all';return heading('Omni Markets',`${marketCoverageLabel()} · ${timestamp(latest().observed_at)}`,'TRADING ACTIVITY',`<button class="button" type="button" data-export-markets>Export markets</button>`)+pageRangeToolbar()+apiNotice()+`<div class="subnav"><a class="${contract==='all'?'active':''}" href="#/omni">Markets</a><a class="${contract==='perpetual'?'active':''}" href="#/omni?contract=perpetual">Perpetuals</a><a class="${contract==='swap'?'active':''}" href="#/omni?contract=swap">Swaps</a></div><div class="grid two">${contractActivityPanels(contract)}</div>${contract==='all'?productMix():''}<section class="panel section-space"><div class="panel-head"><div><h2>Market Overview</h2><p class="panel-subtitle">USDC · indicative full spread at $100K notional</p></div>${infoButton('markets')}</div><div class="table-toolbar"><label class="search-field"><input type="search" placeholder="Search markets" aria-label="Search markets" data-market-search value="${e(state.marketSearch)}"></label><div class="table-count">Select a market for quotes & funding</div></div><div id="market-table">${marketTable()}</div></section>${executionPanel()}`;}
function quoteIssue(market, key) {
  const issue = market.source_warnings?.find(item => item.field === 'quotes.'+key && item.code === 'zero_indicative_quote_price');
  if (!issue) return '';
  const sides = issue.source_fields.map(field => field.split('.').at(-1));
  return 'Source reported zero ' + sides.join(' and ');
}
function marketDetail(m){const q=m.quotes||{},funding=m.funding||{};const quoteRows=[['base','Base'],['size_1k','$1,000'],['size_100k','$100,000'],['size_1m','$1,000,000']];const l=n(m.long_open_interest_usdc),s=n(m.short_open_interest_usdc);return heading(m.ticker,`${m.name} · ${m.contract_type==='swap'?'Swap':'Perpetual'} · ${timestamp(latest().observed_at)}`,'OMNI MARKET DETAIL',`<a class="button" href="#/omni">All markets</a><button class="button" type="button" data-export-quotes="${e(marketKey(m))}">Export quotes</button>`)+pageRangeToolbar()+`<div class="stats">${stat('Mark Price',price(m.mark_price),'<span class="unit">USDC</span>','prices')}${stat('24-Hour Volume',compact(m.volume_24h_usdc),'<span class="unit">USDC</span> · rolling window','volume')}${stat('Trader Open Interest',compact(m.trader_open_interest_usdc),'<span class="unit">USDC</span> · OLP excluded','oi')}${stat('Long Share',percent(ratio(l,(l||0)+(s||0))),'Long / total trader open interest','oi')}</div><div class="grid two">${chartPanel({id:'market-volume',title:'24-Hour Volume · '+m.ticker,subtitle:'USDC · dated observations',rows:historyRows('volume_24h_usdc',m),series:[{key:'value',label:'24H volume',color:BLUE}],type:'bar',unit:'USDC',method:'market-history',maxGapDays:1,note:'Actual observations only · missing points are gaps'})}${chartPanel({id:'market-oi',title:'Trader Open Interest · '+m.ticker,subtitle:'USDC · OLP excluded',rows:historyRows('trader_open_interest_usdc',m),series:[{key:'value',label:'Trader OI',color:TEAL}],type:'bar',unit:'USDC',method:'oi',maxGapDays:1,note:'Missing listings remain unavailable'})}</div><div class="grid two section-space">${panel('Indicative Quotes by Size','Prices in USDC · source notional convention',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Notional</th><th class="number">Bid</th><th class="number">Ask</th><th class="number">Full spread, bps</th></tr></thead><tbody>${quoteRows.map(([key,label])=>`<tr><td>${label}${quoteIssue(m,key) ? '<span class="market-name">'+e(quoteIssue(m,key))+'</span>' : ''}</td><td class="number">${price(q[key]?.bid)}</td><td class="number">${price(q[key]?.ask)}</td><td class="number">${fixed(q[key]?.full_spread_bps,2)}</td></tr>`).join('')}</tbody></table></div>${sourceFooter(DATA.markets.source.url,'Omni API',timestamp(q.updated_at))}`,'quotes')}${fundingPanel(m,funding)}</div>`;}
